```json
{
  "schema": "rar-change-request/1.0",
  "request_id": "req_27119b48ea734411a82274a931960e95",
  "idempotency_key": "req_27119b48ea734411a82274a931960e95",
  "operation": "create",
  "resource": {
    "kind": "agent",
    "id": "@kody-w/parallel_dimensions_agent"
  },
